<?php
require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/layout.php'; require_role('TI'); check_csrf();
$allowed=['setores','locais','categorias']; if($_SERVER['REQUEST_METHOD']==='POST'){ $t=$_POST['tipo']; if(in_array($t,$allowed,true)){ if(!empty($_POST['id'])){$st=$pdo->prepare("UPDATE $t SET nome=?, descricao=?, ativo=? WHERE id=?");$st->execute([$_POST['nome'],$_POST['descricao'],isset($_POST['ativo'])?1:0,(int)$_POST['id']]);} else {$st=$pdo->prepare("INSERT INTO $t (nome,descricao,ativo) VALUES (?,?,1)");$st->execute([$_POST['nome'],$_POST['descricao']]);}} header('Location: ' . app_path('cadastros')); exit; }
render_header('Cadastros');
function bloco($pdo,$tipo,$titulo){$rows=$pdo->query("SELECT * FROM $tipo ORDER BY nome")->fetchAll();?>
<div class="col-lg-4"><div class="card p-3 h-100"><h2 class="h5"><?= e($titulo) ?></h2><form method="post" class="row g-2 mb-3"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="tipo" value="<?= e($tipo) ?>"><div class="col-12"><input class="form-control" name="nome" placeholder="Nome" required></div><div class="col-12"><input class="form-control" name="descricao" placeholder="Descrição"></div><div class="col-12"><button class="btn btn-primary w-100">Adicionar</button></div></form><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Nome</th><th>Ativo</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['nome']) ?></td><td><?= $r['ativo']?'Sim':'Não' ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php }
?>
<h1 class="h3 mb-3">Cadastros básicos</h1><div class="row g-3"><?php bloco($pdo,'setores','Setores'); bloco($pdo,'locais','Locais'); bloco($pdo,'categorias','Categorias'); ?></div><?php render_footer(); ?>
